import { Accessor, For, JSX } from "solid-js";

import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

export interface AlternatingRows<T, U extends JSX.Element> {
	each: T[];
	children: (item: T, index: Accessor<number>) => U;
	rowClass?: string;
	/** Default: bg-primary-4 */
	evenClass?: string;
	/** Default: bg-primary-5 */
	oddClass?: string;
}

function AlternatingRowsComponent<T, U extends JSX.Element>(props: AlternatingRows<T, U>) {
	function getRowClass(index: number) {
		return index % 2 == 0 ? (props.evenClass ?? "bg-primary-4") : (props.oddClass ?? "bg-primary-5");
	}

	return (
		<For each={props.each}>
			{(item, index) => (
				<div class={`${props.rowClass ?? ""} ${getRowClass(index())}`}>{props.children(item, index)}</div>
			)}
		</For>
	);
}

export const AlternatingRows = ComponentRegistry.register("AlternatingRows", AlternatingRowsComponent);
